static void WATER_FillInFarMesh(void)
{
#ifdef TARGET_GC
	u_int vertcolornear=WAVETEX_GCNearColor();
	u_int vertcolorfar= WAVETEX_GCFarColor();
	float gcfadescale=  WAVETEX_GCNFFadeScale();
	float gcfadeoffset= WAVETEX_GCNFFadeOffset();
#endif

	float X[4] = {
		-WATER_InfinityX,
		min(WAVE_MeshMinX - WATER_SeamSizeX, WATER_MeshMinX),
		max(WAVE_MeshMaxX + WATER_SeamSizeX, WATER_MeshMaxX),
		WATER_InfinityX,
	};
	float Z[4] = {
		-WATER_InfinityZ,
		min(WAVE_MeshMinZ - WATER_SeamSizeZ, WATER_MeshMinZ),
		max(WAVE_MeshMaxZ + WATER_SeamSizeZ, WATER_MeshMaxZ),
		WATER_InfinityZ,
	};

	// Go to a lot of trouble to get around the tiling limits.  (dc 07/08/02)
	float Ulo[4];
	float Vlo[4];
	float Uhi[4];
	float Vhi[4];

	const float &umin = WATER_TexMinU, &umax = WATER_TexMaxU;
	const float &vmin = WATER_TexMinV, &vmax = WATER_TexMaxV;
/*	assert(
		-WATER_InfinityX < WATER_MeshMinX &&
		WATER_InfinityX > WATER_MeshMaxX &&
		-WATER_InfinityZ < WATER_MeshMinZ &&
		WATER_InfinityZ > WATER_MeshMaxZ &&
		-WATER_InfinityX < WAVE_MeshMinX &&
		WATER_InfinityX > WAVE_MeshMaxX &&
		-WATER_InfinityZ < WAVE_MeshMinZ &&
		WATER_InfinityZ > WAVE_MeshMaxZ
	);*/

	WATER_TextureCoord(X[1], Z[1], Ulo[1], Vlo[1]);
	WATER_TextureCoord(X[2], Z[2], Uhi[2], Vhi[2]);

	float usign = (WATER_ScaleU > 0) ? 1 : -1;	// to handle flipped tiling (dc 06/18/02)

	Uhi[1] = Ulo[1] - ((int) Ulo[1]) + usign * (umax - 1);
	Ulo[0] = Uhi[1] - usign * ((umax - umin) + 2);
	Ulo[2] = Uhi[2] - ((int) Uhi[2]) + usign * (umin + 1);
	Uhi[3] = Ulo[2] + usign * ((umax - umin) - 2);

	X[0] = X[1] - (Uhi[1] - Ulo[0]) / WATER_ScaleU;
	X[3] = X[2] + (Uhi[3] - Ulo[2]) / WATER_ScaleU;

	float vsign = (WATER_ScaleV > 0) ? 1 : -1;	// to handle flipped tiling (dc 06/18/02)

	Vhi[1] = Vlo[1] - ((int) Vlo[1]) + vsign * (vmax - 1);
	Vlo[0] = Vhi[1] - vsign * ((vmax - vmin) + 2);
	Vlo[2] = Vhi[2] - ((int) Vhi[2]) + vsign * (vmin + 1);
	Vhi[3] = Vlo[2] + vsign * ((vmax - vmin) - 2);

	Z[0] = Z[1] - (Vhi[1] - Vlo[0]) / WATER_ScaleV;
	Z[3] = Z[2] + (Vhi[3] - Vlo[2]) / WATER_ScaleV;

	const float y = 0;
	const float nx = 0, ny = 1, nz = 0;
	const u_int colorin = COLOR_GRAY;
#ifdef TARGET_PS2
	const u_int colorout = ALPHA_TRANSPARENT | (~ALPHA_OPAQUE & COLOR_GRAY);
#else
	const u_int &colorout = colorin;
#endif
	u_int vertcolor;
	float x, z;
	float u, v;
	float xin, zin, xout, zout;
	float uin, vin, uout, vout;
	u_int vertcount = 0;
	u_int xstep, zstep;

	// low Z side
	nglMeshWriteStrip(FarStripSizeX);
	zin = Z[1];
	vin = Vhi[1];
	zout = Z[0];
	vout = Vlo[0];

	for (xstep = 0; xstep <= WATER_MeshStepX; ++xstep)
	{
		vertcount += 2;

		x = WATER_MeshGridX[xstep];
		z = zin;
		u = WATER_MeshGridU[xstep];
		v = vin;
		vertcolor = colorin;
		#ifdef TARGET_GC
			WATER_SubmitVertex(x, y, z, nx, ny, nz, WATER_Transparency(vertcolorfar,vertcolornear,x,y,z,gcfadescale,gcfadeoffset), u, v);
		#else
			WATER_SubmitVertex(x, y, z, nx, ny, nz, vertcolor, u, v);
		#endif

		x = WATER_MeshGridX[xstep];
		z = zout;
		u = WATER_MeshGridU[xstep];
		v = vout;
		vertcolor = colorout;
		#ifdef TARGET_GC
			WATER_SubmitVertex(x, y, z, nx, ny, nz, WATER_Transparency(vertcolorfar,vertcolornear,x,y,z,gcfadescale,gcfadeoffset), u, v);
		#else
			WATER_SubmitVertex(x, y, z, nx, ny, nz, vertcolor, u, v);
		#endif
	}

	// high Z side
	nglMeshWriteStrip(FarStripSizeZ);
	zin = Z[2];
	vin = Vlo[2];
	zout = Z[3];
	vout = Vhi[3];

	for (xstep = 0; xstep <= WATER_MeshStepX; ++xstep)
	{
		vertcount += 2;

		x = WATER_MeshGridX[xstep];
		z = zin;
		u = WATER_MeshGridU[xstep];
		v = vin;
		vertcolor = colorin;
		#ifdef TARGET_GC
			WATER_SubmitVertex(x, y, z, nx, ny, nz, WATER_Transparency(vertcolorfar,vertcolornear,x,y,z,gcfadescale,gcfadeoffset), u, v);
		#else
			WATER_SubmitVertex(x, y, z, nx, ny, nz, vertcolor, u, v);
		#endif

		x = WATER_MeshGridX[xstep];
		z = zout;
		u = WATER_MeshGridU[xstep];
		v = vout;
		vertcolor = colorout;
		#ifdef TARGET_GC
			WATER_SubmitVertex(x, y, z, nx, ny, nz, WATER_Transparency(vertcolorfar,vertcolornear,x,y,z,gcfadescale,gcfadeoffset), u, v);
		#else
			WATER_SubmitVertex(x, y, z, nx, ny, nz, vertcolor, u, v);
	 	#endif
	}

	// low X side
	nglMeshWriteStrip(FarStripSizeX);
	xin = X[1];
	uin = Uhi[1];
	xout = X[0];
	uout = Ulo[0];

	for (zstep = 0; zstep <= WATER_MeshStepZ; ++zstep)
	{
		vertcount += 2;

		x = xin;
		z = WATER_MeshGridZ[zstep];
		u = uin;
		v = WATER_MeshGridV[zstep];
		vertcolor = colorin;
		#ifdef TARGET_GC
			WATER_SubmitVertex(x, y, z, nx, ny, nz, WATER_Transparency(vertcolorfar,vertcolornear,x,y,z,gcfadescale,gcfadeoffset), u, v);
		#else
			WATER_SubmitVertex(x, y, z, nx, ny, nz, vertcolor, u, v);
		#endif

		x = xout;
		z = WATER_MeshGridZ[zstep];
		u = uout;
		v = WATER_MeshGridV[zstep];
		vertcolor = colorout;
		#ifdef TARGET_GC
			WATER_SubmitVertex(x, y, z, nx, ny, nz, WATER_Transparency(vertcolorfar,vertcolornear,x,y,z,gcfadescale,gcfadeoffset), u, v);
		#else
			WATER_SubmitVertex(x, y, z, nx, ny, nz, vertcolor, u, v);
		#endif
	}

	// high X side
	nglMeshWriteStrip(FarStripSizeZ);
	xin = X[2];
	uin = Ulo[2];
	xout = X[3];
	uout = Uhi[3];

	for (zstep = 0; zstep <= WATER_MeshStepZ; ++zstep)
	{
		vertcount += 2;

		x = xin;
		z = WATER_MeshGridZ[zstep];
		u = uin;
		v = WATER_MeshGridV[zstep];
		vertcolor = colorin;
		#ifdef TARGET_GC
			WATER_SubmitVertex(x, y, z, nx, ny, nz, WATER_Transparency(vertcolorfar,vertcolornear,x,y,z,gcfadescale,gcfadeoffset), u, v);
		#else
			WATER_SubmitVertex(x, y, z, nx, ny, nz, vertcolor, u, v);
		#endif

		x = xout;
		z = WATER_MeshGridZ[zstep];
		u = uout;
		v = WATER_MeshGridV[zstep];
		vertcolor = colorout;
		#ifdef TARGET_GC
			WATER_SubmitVertex(x, y, z, nx, ny, nz, WATER_Transparency(vertcolorfar,vertcolornear,x,y,z,gcfadescale,gcfadeoffset), u, v);
		#else
			WATER_SubmitVertex(x, y, z, nx, ny, nz, vertcolor, u, v);
		#endif
	}

	// low X low Z corner
	nglMeshWriteStrip(4);
	xin = X[1];
	uin = Uhi[1];
	xout = X[0];
	uout = Ulo[0];
	zin = Z[1];
	vin = Vhi[1];
	zout = Z[0];
	vout = Vlo[0];

	vertcount += 4;

	x = xin;
	z = zin;
	u = uin;
	v = vin;
	vertcolor = colorin;
	#ifdef TARGET_GC
		WATER_SubmitVertex(x, y, z, nx, ny, nz, WATER_Transparency(vertcolorfar,vertcolornear,x,y,z,gcfadescale,gcfadeoffset), u, v);
	#else
		WATER_SubmitVertex(x, y, z, nx, ny, nz, vertcolor, u, v);
	#endif

	x = xin;
	z = zout;
	u = uin;
	v = vout;
	vertcolor = colorout;
	#ifdef TARGET_GC
		WATER_SubmitVertex(x, y, z, nx, ny, nz, WATER_Transparency(vertcolorfar,vertcolornear,x,y,z,gcfadescale,gcfadeoffset), u, v);
	#else
		WATER_SubmitVertex(x, y, z, nx, ny, nz, vertcolor, u, v);
	#endif

	x = xout;
	z = zin;
	u = uout;
	v = vin;
	vertcolor = colorout;
	#ifdef TARGET_GC
		WATER_SubmitVertex(x, y, z, nx, ny, nz, WATER_Transparency(vertcolorfar,vertcolornear,x,y,z,gcfadescale,gcfadeoffset), u, v);
	#else
		WATER_SubmitVertex(x, y, z, nx, ny, nz, vertcolor, u, v);
	#endif

	x = xout;
	z = zout;
	u = uout;
	v = vout;
	vertcolor = colorout;
	#ifdef TARGET_GC
		WATER_SubmitVertex(x, y, z, nx, ny, nz, WATER_Transparency(vertcolorfar,vertcolornear,x,y,z,gcfadescale,gcfadeoffset), u, v);
	#else
		WATER_SubmitVertex(x, y, z, nx, ny, nz, vertcolor, u, v);
	#endif

	// low X high Z corner
	nglMeshWriteStrip(4);
	xin = X[1];
	uin = Uhi[1];
	xout = X[0];
	uout = Ulo[0];
	zin = Z[2];
	vin = Vlo[2];
	zout = Z[3];
	vout = Vhi[3];

	vertcount += 4;

	x = xin;
	z = zin;
	u = uin;
	v = vin;
	vertcolor = colorin;
	#ifdef TARGET_GC
		WATER_SubmitVertex(x, y, z, nx, ny, nz, WATER_Transparency(vertcolorfar,vertcolornear,x,y,z,gcfadescale,gcfadeoffset), u, v);
	#else
		WATER_SubmitVertex(x, y, z, nx, ny, nz, vertcolor, u, v);
	#endif

	x = xin;
	z = zout;
	u = uin;
	v = vout;
	vertcolor = colorout;
	#ifdef TARGET_GC
		WATER_SubmitVertex(x, y, z, nx, ny, nz, WATER_Transparency(vertcolorfar,vertcolornear,x,y,z,gcfadescale,gcfadeoffset), u, v);
	#else
		WATER_SubmitVertex(x, y, z, nx, ny, nz, vertcolor, u, v);
	#endif

	x = xout;
	z = zin;
	u = uout;
	v = vin;
	vertcolor = colorout;
	#ifdef TARGET_GC
		WATER_SubmitVertex(x, y, z, nx, ny, nz, WATER_Transparency(vertcolorfar,vertcolornear,x,y,z,gcfadescale,gcfadeoffset), u, v);
	#else
		WATER_SubmitVertex(x, y, z, nx, ny, nz, vertcolor, u, v);
	#endif

	x = xout;
	z = zout;
	u = uout;
	v = vout;
	vertcolor = colorout;
	#ifdef TARGET_GC
		WATER_SubmitVertex(x, y, z, nx, ny, nz, WATER_Transparency(vertcolorfar,vertcolornear,x,y,z,gcfadescale,gcfadeoffset), u, v);
	#else
		WATER_SubmitVertex(x, y, z, nx, ny, nz, vertcolor, u, v);
	#endif

	// high X low Z corner
	nglMeshWriteStrip(4);
	xin = X[2];
	uin = Ulo[2];
	xout = X[3];
	uout = Uhi[3];
	zin = Z[1];
	vin = Vhi[1];
	zout = Z[0];
	vout = Vlo[0];

	vertcount += 4;

	x = xin;
	z = zin;
	u = uin;
	v = vin;
	vertcolor = colorin;
	#ifdef TARGET_GC
		WATER_SubmitVertex(x, y, z, nx, ny, nz, WATER_Transparency(vertcolorfar,vertcolornear,x,y,z,gcfadescale,gcfadeoffset), u, v);
	#else
		WATER_SubmitVertex(x, y, z, nx, ny, nz, vertcolor, u, v);
	#endif

	x = xin;
	z = zout;
	u = uin;
	v = vout;
	vertcolor = colorout;
	#ifdef TARGET_GC
		WATER_SubmitVertex(x, y, z, nx, ny, nz, WATER_Transparency(vertcolorfar,vertcolornear,x,y,z,gcfadescale,gcfadeoffset), u, v);
	#else
		WATER_SubmitVertex(x, y, z, nx, ny, nz, vertcolor, u, v);
	#endif

	x = xout;
	z = zin;
	u = uout;
	v = vin;
	vertcolor = colorout;
	#ifdef TARGET_GC
		WATER_SubmitVertex(x, y, z, nx, ny, nz, WATER_Transparency(vertcolorfar,vertcolornear,x,y,z,gcfadescale,gcfadeoffset), u, v);
	#else
		WATER_SubmitVertex(x, y, z, nx, ny, nz, vertcolor, u, v);
	#endif

	x = xout;
	z = zout;
	u = uout;
	v = vout;
	vertcolor = colorout;
	#ifdef TARGET_GC
		WATER_SubmitVertex(x, y, z, nx, ny, nz, WATER_Transparency(vertcolorfar,vertcolornear,x,y,z,gcfadescale,gcfadeoffset), u, v);
	#else
		WATER_SubmitVertex(x, y, z, nx, ny, nz, vertcolor, u, v);
	#endif

	// low X high Z corner
	nglMeshWriteStrip(4);
	xin = X[2];
	uin = Ulo[2];
	xout = X[3];
	uout = Uhi[3];
	zin = Z[2];
	vin = Vlo[2];
	zout = Z[3];
	vout = Vhi[3];

	vertcount += 4;

	x = xin;
	z = zin;
	u = uin;
	v = vin;
	vertcolor = colorin;
	#ifdef TARGET_GC
		WATER_SubmitVertex(x, y, z, nx, ny, nz, WATER_Transparency(vertcolorfar,vertcolornear,x,y,z,gcfadescale,gcfadeoffset), u, v);
	#else
		WATER_SubmitVertex(x, y, z, nx, ny, nz, vertcolor, u, v);
	#endif

	x = xin;
	z = zout;
	u = uin;
	v = vout;
	vertcolor = colorout;
	#ifdef TARGET_GC
		WATER_SubmitVertex(x, y, z, nx, ny, nz, WATER_Transparency(vertcolorfar,vertcolornear,x,y,z,gcfadescale,gcfadeoffset), u, v);
	#else
		WATER_SubmitVertex(x, y, z, nx, ny, nz, vertcolor, u, v);
	#endif

	x = xout;
	z = zin;
	u = uout;
	v = vin;
	vertcolor = colorout;
	#ifdef TARGET_GC
		WATER_SubmitVertex(x, y, z, nx, ny, nz, WATER_Transparency(vertcolorfar,vertcolornear,x,y,z,gcfadescale,gcfadeoffset), u, v);
	#else
		WATER_SubmitVertex(x, y, z, nx, ny, nz, vertcolor, u, v);
	#endif

	x = xout;
	z = zout;
	u = uout;
	v = vout;
	vertcolor = colorout;
	#ifdef TARGET_GC
		WATER_SubmitVertex(x, y, z, nx, ny, nz, WATER_Transparency(vertcolorfar,vertcolornear,x,y,z,gcfadescale,gcfadeoffset), u, v);
	#else
		WATER_SubmitVertex(x, y, z, nx, ny, nz, vertcolor, u, v);
	#endif

	assert(vertcount == FarMeshNumVert);
}
